// ---- Three independent style axes ----

/** Font / typeface selection */
export type FontId = "minimal" | "editorial" | "clean" | "mono" | "condensed";

/** Surface — bg + text neutrals (no pop color). */
export type SurfaceId =
  | "dark"
  | "white"
  | "light"
  | "paper"
  | "gradient"
  | "pastel"
  | "neon"
  | "ember";

/** Accent — the pop color used for highlighted words. */
export type AccentId =
  | "yellow"
  | "red"
  | "teal"
  | "coral"
  | "orange"
  | "violet"
  | "lime"
  | "blue"
  | "fuchsia"
  | "pink"
  | "amber";

/** Layout purpose — drives typography scale */
export type PurposeId = "carousel" | "presentation";

/**
 * Curated complete looks. A look pins the style axes to a combination that has
 * been checked, and may override typography beyond what the axes can express.
 * "none" leaves the three axes under manual control.
 */
export type LookId =
  | "none"
  | "soft-organic"
  | "aurora"
  | "stealth"
  | "swiss"
  | "vista"
  | "editorial-look"
  | "organic"
