  titleTransform?: "none" | "lowercase" | "uppercase";
  /**
   * Which rule set a look belongs to. "supaslides" looks share one
   * typographic core (Manrope 800 lowercase, tonal emphasis). "standalone"
   * looks deliberately do not — see the caption/maximalist spec. Absent
   * means unclassified.
   */
