  /** Boxed treatment applied to headline, stat numeral and quote. */
  panelStyle?: "caption" | "sticker";
  panelBg?: string;
  panelText?: string;
  panelBorder?: string;
  /** Hard offset shadow, in em, e.g. 0.26. Omitted means no shadow. */
  panelShadow?: number;
  /** Panel border width in cqw. Defaults to 1.2. */
  panelBorderCqw?: number;
  /** Max panel width in cqw, so the box hugs its copy instead of the column. */
