  /** Corner radius in em. 0 for hard corners. */
  panelRadius?: number;
  /** Base rotation in degrees. Sign alternates by slide index. */
  panelRotate?: number;
  /** Padding in em, as [top, x, bottom]. */
  panelPad?: [number, number, number];
  titleDivider?: boolean;
  titleColor?: string;
  // Body text overrides — defaults: 600, textColor, lineHeight 1.2
  bodyFontWeight?: number;
  bodyColor?: string;
  bodyLineHeight?: number;
  /** Body-headline typeface. Defaults to fontFamily. */
  bodyFontFamily?: string;
  // Subtext overrides — the lighter paragraph under the headline.
  // Distinct from body*, which styles the body slide's own headline.
  subFontFamily?: string;
  subFontWeight?: number;
  subColor?: string;
  subLineHeight?: number;
  // Hook overrides — defaults: 800, textColor, lineHeight 1.02, no transform
